mapper.select:
SELECT T1.LIST_ID, T1.LIST_DATE, T3.UPDATE_USER, T2.CRT_USER, case when T2.NEXT_USER IS NULL then T2.CUR_USER else T2.NEXT_USER end spr, T1.WORKFLOW_ID
FROM ( SELECT LIST_ID, LIST_DATE, WORKFLOW_ID FROM WFL_RSK_ACCESS_LIST_LOG
LIST_ID = #{listId,jdbcType=VARCHAR}
GROUP BY LIST_ID, LIST_DATE, WORKFLOW_ID ) T1 LEFT JOIN SYS_WFL_BUSINESS_LIST T2 ON T1.WORKFLOW_ID = T2.SEQ_NO LEFT JOIN WFL_RSK_ACCESS_LIST T3 ON T3.LIST_ID = T1.LIST_ID
T1.LIST_ID = #{listId,jdbcType=VARCHAR}
UNION ALL SELECT T1.LIST_ID, T1.LIST_DATE, T5.UPDATE_USER, T4.CRT_USER, T4.NEXT_USER spr, NULL WORKFLOW_ID
FROM ( SELECT LIST_ID, LIST_DATE, UPDATE_TIME FROM ( SELECT LIST_ID, LIST_DATE, DATE_FORMAT ( UPDATE_TIME, '%Y-%m-%d' ) UPDATE_TIME FROM RSK_ACCESS_LIST_LOG ) GROUP BY LIST_ID, LIST_DATE, UPDATE_TIME ) T1 LEFT JOIN RSK_ACCESS_LIST T5 ON T5.LIST_ID = T1.LIST_ID LEFT JOIN ( SELECT T3.TRADE_ID, T3.UPDATE_USER, T2.UPDATE_TIME, T3.CRT_USER, case when T3.NEXT_USER IS NULL then T3.CUR_USER else T3.NEXT_USER end NEXT_USER FROM ( SELECT MAX( SEQ_NO ) SEQ_NO, DATE_FORMAT ( UPDATE_TIME, '%Y-%m-%d' ) UPDATE_TIME FROM SYS_WFL_BUSINESS_LIST
PAGE_ID = #{pageId,jdbcType=VARCHAR}
AND TRADE_ID = #{listId,jdbcType=VARCHAR}
AND PROCESS_STATE ='END'
GROUP BY DATE_FORMAT ( UPDATE_TIME, '%Y-%m-%d' ) ) T2 LEFT JOIN SYS_WFL_BUSINESS_LIST T3 ON T2.SEQ_NO = T3.SEQ_NO ) T4 ON T1.LIST_ID = T4.TRADE_ID AND T1.UPDATE_TIME = T4.UPDATE_TIME WHERE NOT EXISTS ( SELECT LIST_ID, LIST_DATE, WORKFLOW_ID FROM WFL_RSK_ACCESS_LIST_LOG WHERE LIST_ID = T1.LIST_ID AND LIST_DATE = T1.LIST_DATE GROUP BY LIST_ID, LIST_DATE, WORKFLOW_ID )
AND T1.LIST_ID = #{listId,jdbcType=VARCHAR}

mapper.delete:
delete from RSK_ACCESS_LIST_LOG
where LIST_ID = #{listId,jdbcType=VARCHAR}
  and LIST_DATE = #{sysDate,jdbcType=DATE}
